    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        List<String[]> employees = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            employees.add(new String[]{st.nextToken(), st.nextToken()});
        }
        TreeMap<String, List<String>> groups = groupByDepartment(employees);
        StringBuilder sb = new StringBuilder();
        for (Map.Entry<String, List<String>> e : groups.entrySet()) {
            sb.append("Department: ").append(e.getKey()).append("\n");
            for (String name : e.getValue()) sb.append("  Employee: ").append(name).append("\n");
        }
        System.out.print(sb);
    }
}

