def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyz'
    def name():
        return rng.choice('ABCDEFGHIJKLMNOPQRSTUVWXYZ') + ''.join(rng.choice(letters) for _ in range(rng.randint(0, 9)))
    def local():
        return ''.join(rng.choice(letters + '0123456789.') for _ in range(rng.randint(1, 10)))
    def domain(pool):
        return rng.choice(pool)
    def fmt(rows):
        return str(len(rows)) + '\n' + '\n'.join(f"{a} {b}" for a, b in rows)
    tests = [
        fmt([("A", "a@x")]),
        fmt([("Al", "a@x.com"), ("Al", "b@x.com"), ("Al", "c@x.com")]),
        fmt([("B", "q@z.a"), ("C", "q@z.b"), ("D", "q@y.z")]),
        fmt([("Eve", "e@d1"), ("Fay", "f@d10"), ("Gus", "g@d1.0"), ("Hal", "h@d2")]),
    ]
    for _ in range(5):
        pool = [''.join(rng.choice('abc.') for _ in range(rng.randint(1, 4))) for _ in range(rng.randint(1, 4))]
        n = rng.randint(1, 10)
        tests.append(fmt([(name(), local() + '@' + domain(pool)) for _ in range(n)]))
    n = 30000
    pool = [''.join(rng.choice(letters + '0123456789.') for _ in range(rng.randint(1, 15))) for _ in range(2000)]
    tests.append(fmt([(name(), local() + '@' + domain(pool)) for _ in range(n)]))
    pool = ['corp.com']
